#[test]
fn test_reference_vectors() -> Result<(), Ed25519Error> {
    let random = core::array::from_fn(|i| i as u8);
    for (secret, message, public, expected_signature) in TEST_VECTORS {
        let secret = SecretKey::try_from(*secret)?;
        let signing = secret.as_signing_key();
        let converted = secret.generate_curve25519_pubkey()?.as_signing_key()?;
        assert_eq_hex_slice!(signing.public_key().as_ref(), public);
        assert_eq_hex_slice!(converted.as_ref(), public);
        let signature = signing.sign_message(message, &random);
        assert_eq_hex_slice!(signature.signature, expected_signature);
        converted.verify_signed_message(message, &signature.signature)?;
        signature.validate_hash(message)?;
    }
    Ok(())
}

#[test]
fn test_clamping_equivalence() -> Result<(), Ed25519Error> {
    let mut bytes = [0x42; 32];
    let secret = SecretKey::try_from(bytes)?;
    let signing = secret.as_signing_key();
    bytes[0] ^= 7;
    bytes[31] ^= 0xC0;
    let equivalent = SecretKey::try_from(bytes)?;
    let equivalent_signing = equivalent.as_signing_key();
    assert_eq_hex_slice!(
        signing.public_key().as_ref(),
        equivalent_signing.public_key().as_ref()
    );
    let public: [u8; 32] = *secret.generate_curve25519_pubkey()?.as_ref();
    let equivalent_public: [u8; 32] = *equivalent.generate_curve25519_pubkey()?.as_ref();
    assert_eq_hex_slice!(public, equivalent_public);
    let signature = signing.sign_message(b"clamping", &[3; 64]);
    let equivalent_signature = equivalent_signing.sign_message(b"clamping", &[3; 64]);
    assert_eq_hex_slice!(signature.signature, equivalent_signature.signature);
    Ok(())
}

#[test]
fn test_randomness_and_tampering() -> Result<(), Ed25519Error> {
    let secret = SecretKey::try_from([0x42; 32])?;
    let signing = secret.as_signing_key();
    let public = secret.generate_curve25519_pubkey()?.as_signing_key()?;
    let message = [0x5A; 257];
    let first = signing.sign_message(&message, &[0; 64]);
    let second = signing.sign_message(&message, &[1; 64]);
    assert_ne!(first.signature, second.signature);
    public.verify_signed_message(&message, &first.signature)?;
    public.verify_signed_message(&message, &second.signature)?;
    assert!(public
        .verify_signed_message(b"changed", &first.signature)
        .is_err());
    let wrong_key = SecretKey::try_from([0x43; 32])?.as_signing_key();
    assert!(wrong_key
        .public_key()
        .verify_signed_message(&message, &first.signature)
        .is_err());
    for index in [0, 31, 32, 63] {
        let mut tampered = first.signature;
        tampered[index] ^= 1;
        assert!(public.verify_signed_message(&message, &tampered).is_err());
    }
    Ok(())
}
